function asParseGrid(text){
  var lines=String(text).replace(/\r/g,'').split('\n').filter(function(l){ return l.length>0; });
  if(!lines.length) return { value:null, error:'网格为空' };
  var w=lines[0].length, grid=[], start=null, end=null;
  for(var r=0;r<lines.length;r++){
    if(lines[r].length!==w) return { value:null, error:'第 '+(r+1)+' 行宽度不一致' };
    var row=[];
    for(var c=0;c<w;c++){
      var ch=lines[r][c];
      if(ch==='S'){ if(start) return { value:null, error:'多个起点 S' }; start=[r,c]; row.push(0); }
      else if(ch==='E'){ if(end) return { value:null, error:'多个终点 E' }; end=[r,c]; row.push(0); }
      else if(ch==='#') row.push(1);
      else if(ch==='.') row.push(0);
      else return { value:null, error:'非法字符 "'+ch+'" 于 ('+r+','+c+')' };
    }
    grid.push(row);
  }
  if(!start) return { value:null, error:'缺少起点 S' };
  if(!end) return { value:null, error:'缺少终点 E' };
  return { value:{ grid:grid, start:start, end:end, rows:lines.length, cols:w }, error:null };
}
function asFindPath(parsed){
  var g=parsed.grid, R=parsed.rows, C=parsed.cols;
  var sr=parsed.start[0], sc=parsed.start[1], er=parsed.end[0], ec=parsed.end[1];
  function h(r,c){ return Math.abs(r-er)+Math.abs(c-ec); }
  var INF=Infinity;
  var gScore=[], came=[], closed=[];
  for(var i=0;i<R;i++){ gScore.push([]); came.push([]); closed.push([]);
    for(var j=0;j<C;j++){ gScore[i].push(INF); came[i].push(null); closed[i].push(false); } }
  gScore[sr][sc]=0;
  var open=[[sr,sc]];
  var expanded=0;
  var DIRS=[[-1,0],[1,0],[0,-1],[0,1]];
  while(open.length){
    var best=0;
    for(var k=1;k<open.length;k++){
      var a=open[k], b=open[best];
      if(gScore[a[0]][a[1]]+h(a[0],a[1]) < gScore[b[0]][b[1]]+h(b[0],b[1])) best=k;
    }
    var cur=open.splice(best,1)[0];
    var r=cur[0], c=cur[1];
    if(closed[r][c]) continue;
    closed[r][c]=true; expanded++;
    if(r===er&&c===ec){
      var path=[[r,c]];
      while(came[r][c]){ var p=came[r][c]; path.push(p); r=p[0]; c=p[1]; }
      path.reverse();
      return { value:{ path:path, cost:path.length-1, expanded:expanded }, error:null };
    }
    for(var d=0;d<4;d++){
      var nr=r+DIRS[d][0], nc=c+DIRS[d][1];
      if(nr<0||nr>=R||nc<0||nc>=C||g[nr][nc]===1||closed[nr][nc]) continue;
      var ng=gScore[r][c]+1;
      if(ng<gScore[nr][nc]){ gScore[nr][nc]=ng; came[nr][nc]=[r,c]; open.push([nr,nc]); }
    }
  }
  return { value:null, error:'无可达路径' };
}
function asRender(parsed, path){
  var mark={};
  for(var i=0;i<path.length;i++) mark[path[i][0]+','+path[i][1]]=true;
  var out=[];
  for(var r=0;r<parsed.rows;r++){
    var line='';
    for(var c=0;c<parsed.cols;c++){
      if(r===parsed.start[0]&&c===parsed.start[1]) line+='S';
      else if(r===parsed.end[0]&&c===parsed.end[1]) line+='E';
      else if(parsed.grid[r][c]===1) line+='#';
      else if(mark[r+','+c]) line+='*';
      else line+='.';
    }
    out.push(line);
  }
  return out.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { asParseGrid:asParseGrid, asFindPath:asFindPath, asRender:asRender };
}
if (typeof window !== 'undefined') {
  window.AstarForgePure = { asParseGrid:asParseGrid, asFindPath:asFindPath, asRender:asRender };
}
